architecture.h4_f:
msg = CBOR{v:1, tekst, antwoord_naar, verzonden_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {cijfertekst: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, tekst, antwoord_to?, thread_id?, vermeldingen?, sent_at}
ct = AES-GCM-256-Encrypt(kamer_sleutel, nonce, pt, aad=hex(kamer_id))
draad = CBOR{
  v: 1,
  cijfertekst: hex(ct), // variabele lengte
  nonce: hex(12 B),
  afzender_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
buitenste = CBOR{
  bron_node: hex32,
  doel_gebruiker: int64,
  innerlijke_cijfertekst: bytes,
  inner_nonce: bytes,
  sent_at: unix_ms
}
sig = Ed25519-Sign(bron_priv, buitenste)
POST /federatie/deliver { envelop: buitenste, sig: hex64 }

auth.h1_f:
POST /api/authenticatie/registreren
  { gebruikersnaam, wachtwoord, x25519_public_key, display_name, telefoon?, e-mailadres?, avatar_emoji }

Reactie 201 Gemaakt:
  { access_token, refresh_token, user_id, gebruikersnaam, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, typ: "access", exp: nu + 15min }
refresh_token payload:
  { sub: user_id, jti: device_id, typ: "refresh", exp: nu + 30d }

HS256-ondertekend met het 64-byte geheim van het knooppunt uit .env

auth.h4_f:
register_begin(): uitdaging = rand(32)
                    opties = { rp.id, user.id, pubKeyCredParams, uitdaging }
                    retour mogelijkheden

register_finish(attest):
  verifieer attestatie tegen TPM / Secure Enclave root CA
  winkel { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authenticatie/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nieuw apparaat geregistreerd; JWT's zijn teruggekeerd.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hexadecimaal
cijfertekst = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Uitwaaierframe: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {bestandsnaam, grootte, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finaliseren POST /api/files/resumable/{upload_id}/finaliseren {plain_blake3}
            ← 201 {bestandsid, url}
TTL op onafgewerkt: 24 uur

files.h4_f:
weiger_lijst = {
  "applicatie/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binair",
}
if magic.from_buffer(buf[:1024]) in deny_list: return 415

presence.h1_f:
client: bij de eerste toetsaanslag → verzend {type:"t", state:"start"}
         geen verzending meer gedurende 3 s, tenzij de status verandert
         10 s na de laatste toetsaanslag → verzend {type:"t", state:"stop"}
ontvanger: auto-stop 10 s na de laatste "start" als er geen "stop" is aangekomen

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS uitzending {type:"c", soort:"invite", call_id}
WS uitzending {type:"c", soort:"aanbieding", sdp}
WS uitzending {type:"c", soort:"antwoord", sdp}
WS uitzending {type:"c", soort:"kandidaat",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
envelop = {
  bron_node: hex32,
  doel_gebruiker: int64,
  innerlijke_cijfertekst: bytes,
  inner_nonce: bytes,
  sent_at: unix_ms,
}
sig = Ed25519Sign(bron_priv, CBOR(envelop))
POST /federatie/deliver { envelop, sig }

gossip.h3_f:
advertentie = {pubkey, eindpunt, geadverteerde_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(advertentie))
roddellading: [..., {ad, sig}, ...]

ontvanger: verifieer sig tegen ad.pubkey → sla iff ok op
extra: PoW van 2^18 voorloopnullen op {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template met {
  willekeurig = onze willekeurige,
  servernaam = onze hostnaam (of ECH-verpakt),
  session_id = onze sessie-ID,
}
JA4 = t13d_xxxx_xxxx_xxxx (komt overeen met de huidige Chrome-stabiel)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {naam: x.vortexx.sol}
ECH: ClientHello.extensions += Encrypted_sni(public_key_from_HTTPS_record)
DGA: domein(t) = basis32( SHA256(zaad ∥ YYYY-MM-DD) )[:16] + ".voorbeeld"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
gereedschap = teken_tool
input = bronboom, sleutels/release.key
manifest = {
  versie: "0.1.0",
  build_at: unix_ms,
  bestanden: [{pad, sha256, grootte}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, ondertekend door: pub_hex, sig: sig_hex}

bots.h1_f:
maak: POST /api/bots {gebruikersnaam, displaynaam, code}
          → {bot_id, token, pubkey}
run: in-process (coroutine binnen knooppunt)
      OR extern (lange poll /api/bots/{id}/updates, token-auth'd)
bericht: {tekst, handtekening: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
aan /start {
  zend "Welkom, {ctx.first_name}" uit
}
op /add <item> {
  state.list = (state.list of []) + [ctx.args.item]
  zend "Toegevoegd: {ctx.args.item}"
}

debugging.h2_f:
tariefhistogrammen (per route + methode):
  vortex_http_requests_total{route,methode,status}
  vortex_http_request_duration_seconds_bucket{route,methode,le}

websocket meters:
  vortex_ws_connections{knooppunt}
  vortex_ws_fanout_queue_ depth {kamer, gebruiker}

aangepaste tellers:
  vortex_messages_sent_total{kamertype}
  vortex_calls_started_total{soort}

